#pragma once

// U8 storage (docs/spec/storage.md): CompressedBlocks, Stools, Rope, ShearVines, MorePottedPlants,
// GlassShard, UtilityRecipes.
//
// Files: Storage.cpp (config, content gates, recipe / creative gating, block properties, module),
// Compressed.cpp (fuel, compost, beacon base, glass shards, utility tweaks), Stools.cpp, Rope.cpp,
// Plants.cpp (cut vines, potted plants), StorageTests.cpp. Content.inc is generated by
// tools/pack/storage.ps1.

#include <cstdint>
#include <functional>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

class Actor;
class Block;
class BlockPos;
class BlockSource;
class ItemStack;
class Player;
class Random;

namespace lp::feature::storage {

struct StorageConfig {
    int version = 1;

    // CompressedBlocks
    bool enableCompressedBlocks  = true;
    bool burnsForever            = true;
    int  charcoalBlockFuelTime   = 16000;
    int  blazeLanternFuelTime    = 24000;
    int  stickBlockFuelTime      = 900;
    bool enableCharcoalBlock     = true;
    bool enableSugarCaneBlock    = true;
    bool enableCactusBlock       = true;
    bool enableChorusFruitBlock  = true;
    bool enableStickBlock        = true;
    bool enableAppleCrate        = true;
    bool enableGoldenAppleCrate  = true;
    bool enablePotatoCrate       = true;
    bool enableCarrotCrate       = true;
    bool enableGoldenCarrotCrate = true;
    bool enableBeetrootCrate     = true;
    bool enableCocoaBeanSack     = true;
    bool enableNetherWartSack    = true;
    bool enableGunpowderSack     = true;
    bool enableBerrySack         = true;
    bool enableGlowBerrySack     = true;
    bool enableBlazeLantern      = true;
    bool enableBondedLeather     = true;
    bool enableBondedRabbitHide  = true;

    // Stools
    bool enableStools = true;

    // Rope
    bool enableRope                  = true;
    bool forceEnableMoveTileEntities = false;
    bool enableDispenserBehavior     = true;

    // ShearVines, MorePottedPlants, GlassShard
    bool enableShearVines       = true;
    bool enableMorePottedPlants = true;
    bool enableGlassShard       = true;

    // UtilityRecipes
    bool enableUtilityRecipes    = true;
    bool betterStoneToolCrafting = true;
    bool enableDispenser         = true;
    bool enableRepeater          = true;
    bool enableMinecarts         = true;
    bool enableChestBoats        = true;
    bool logsToChests            = true;
    bool coralToDye              = true;
    bool bentRecipes             = true;
    bool compostableToxins       = true;
    bool effectiveDragonBreath   = true;
    bool torchesBurn             = true;
    bool boneMealUtility         = true;
    bool charcoalToBlackDye      = true;
    bool easyHopper              = true;
    bool easySticks              = true;
    bool smeltRawOreBlocks       = true;
};

[[nodiscard]] StorageConfig const& cfg();

// ---- content gates (Storage.cpp) ----------------------------------------------------------------

/// A config key of this unit by name ("enableRope"); false for unknown keys.
[[nodiscard]] bool flag(std::string_view key);
/// All keys of a comma-separated list are on.
[[nodiscard]] bool gatesOn(std::string_view keys);
/// A block / item id of this unit is enabled (true for ids that aren't ours).
[[nodiscard]] bool contentEnabled(std::string_view id);
/// The recipe should be loaded (our recipes by their gates; vanilla ones this unit replaces).
[[nodiscard]] bool recipeEnabled(std::string_view recipeId);
/// A block / item id of this unit.
[[nodiscard]] bool owns(std::string_view id);
/// Every block / item id this unit owns.
[[nodiscard]] std::vector<std::string_view> contentIds();
/// Every recipe id this unit owns.
[[nodiscard]] std::vector<std::string_view> recipeIds();
/// Sets the game properties of our block types (climbable, infiniburn, correct tool). Idempotent.
void applyBlockProperties();

/// Work for the next server tick (cancelled interaction events roll back changes made in them).
void defer(std::function<void()> fn);
/// The block's lepton tag (`lepton:stool`, ...).
[[nodiscard]] bool hasTag(Block const& block, std::string_view tag);
/// Gives `item` to the player or drops it at their feet.
void giveOrDrop(Player& player, ItemStack const& item);

// ---- CompressedBlocks / UtilityRecipes / GlassShard (Compressed.cpp) ------------------------------

/// Furnace fuel of an item of this unit (or a torch), in Java furnace ticks; nullopt if not ours.
[[nodiscard]] std::optional<int> fuelTicks(std::string_view itemId);
/// Composter chance (percent) for items this unit makes compostable; nullopt if not ours.
[[nodiscard]] std::optional<int> compostChance(std::string_view itemId);
/// Beacon pyramid levels at `beacon` counting golden apple crates as base blocks (0..4).
[[nodiscard]] int beaconLevels(BlockSource& region, BlockPos const& beacon);
/// The shard item a broken block drops ("" when it drops none): glass, stained glass, dirty glass.
[[nodiscard]] std::string shardFor(std::string_view blockId);
/// Shards dropped: uniform 2..4, + uniform 0..fortune, limited to 1..4, explosion decay.
[[nodiscard]] int shardCount(std::uint32_t (*next)(void*), void* rng, int fortune, float explosionRadius);
/// Applies the dragon's breath crafting remainder for the current config.
void applyDragonBreath();
void installCompressed();
void uninstallCompressed();

// ---- Stools (Stools.cpp) -----------------------------------------------------------------------

namespace stools {
/// Seats `player` on the stool at `pos` (Quark StoolBlock#useWithoutItem). False if not possible.
bool sit(Player& player, BlockSource& region, BlockPos const& pos);
/// A block changed next to stools (queues their fixState).
void blockChanged(BlockSource& region, BlockPos const& pos, Block const& newBlock, Block const& below);
/// Recomputes `lepton:big` / `lepton:sat_in` of the stool at `pos` (Quark fixState).
bool fixState(BlockSource& region, BlockPos const& pos);
/// The seat entity a player rides, if any.
[[nodiscard]] Actor* seatOf(Player& player);
/// Runs the seats' tick now (tests).
void tickSeats();
/// Gives the stool block types their bounce and comparator signal (idempotent; also client side).
void applyTypes();
/// The stool block types got the bounce / comparator vtable.
[[nodiscard]] bool typesPatched();
void install();
void uninstall();
} // namespace stools

// ---- Rope (Rope.cpp) ---------------------------------------------------------------------------

namespace rope {
/// Rope can hang at `pos` (rope or a sturdy bottom face above).
[[nodiscard]] bool canHang(BlockSource& region, BlockPos const& pos);
/// Quark RopeBlock#pullDown from the rope at `pos`.
bool pullDown(BlockSource& region, BlockPos const& pos);
/// Quark RopeBlock#pullUp from the rope at `pos`.
bool pullUp(BlockSource& region, BlockPos const& pos);
/// The first non-rope position below the rope column at `pos`.
[[nodiscard]] BlockPos bottomOf(BlockSource& region, BlockPos const& pos);
/// The dispenser behaviour at `front` (rope in front: pull down; air: place). True on success.
bool dispenseAt(BlockSource& region, BlockPos const& front);
/// A block changed next to ropes (queues their survival check).
void blockChanged(BlockSource& region, BlockPos const& pos, Block const& newBlock, Block const& below);
/// Re-reads the PistonsMoveTileEntities rules (U10's config file).
void reloadRules();
/// Pops ropes that lost their support (ran from block changes; exposed for tests).
void checkSurvival(BlockSource& region, BlockPos const& pos);
void install();
void uninstall();
} // namespace rope

// ---- ShearVines / MorePottedPlants (Plants.cpp) ------------------------------------------------

namespace plants {
/// Shears the vine at `pos` into a cut vine and removes the vines below it.
bool shearVine(BlockSource& region, BlockPos const& pos);
/// A block changed next to cut vines (queues their support check).
void blockChanged(BlockSource& region, BlockPos const& pos, Block const& newBlock, Block const& below);
/// Removes unsupported faces of the cut vine at `pos` (removes it with none left).
bool checkCutVine(BlockSource& region, BlockPos const& pos);
/// The potted block for a plant item ("" if the item doesn't fit a pot).
[[nodiscard]] std::string pottedFor(std::string_view itemId);
/// The plant item of a potted block ("" if `blockId` isn't ours).
[[nodiscard]] std::string plantOf(std::string_view blockId);
/// Puts the plant `itemId` into the empty flower pot at `pos`.
bool pot(BlockSource& region, BlockPos const& pos, std::string_view itemId);
/// Takes the plant out of our potted block at `pos`; returns the plant item id ("" if none).
std::string unpot(BlockSource& region, BlockPos const& pos);
void install();
void uninstall();
} // namespace plants

} // namespace lp::feature::storage
